package com.fleet.domain;

/**
 * Where a location reading came from. Used to clearly distinguish development
 * simulation from real device/mobile GPS so simulated points are never presented
 * as real vehicle GPS positions.
 */
public enum LocationSource {
    /** Synthetic positions generated by {@code GpsSimulator} for development. */
    SIMULATED,
    /** Real GPS reported by an authenticated user's mobile browser. */
    MOBILE,
    /** Real GPS reported by an installed telematics/GPS device. */
    DEVICE,
    /** Manually entered by an operator. */
    MANUAL
}
